import { useEffect, useState } from 'react';
import { db, type Player } from '../lib/db';
import { getRatingTier } from '../lib/elo';

export default function Players() {
  const [players, setPlayers] = useState<Player[]>([]);
  const [showForm, setShowForm] = useState(false);
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [form, setForm] = useState({ name: '', email: '', phone: '', rating: '1200' });
  const [search, setSearch] = useState('');

  useEffect(() => {
    loadPlayers();
  }, []);

  async function loadPlayers() {
    const all = await db.players.orderBy('rating').reverse().toArray();
    setPlayers(all);
  }

  function openAddForm() {
    setForm({ name: '', email: '', phone: '', rating: '1200' });
    setEditingPlayer(null);
    setShowForm(true);
  }

  function openEditForm(player: Player) {
    setForm({
      name: player.name,
      email: player.email || '',
      phone: player.phone || '',
      rating: String(player.rating),
    });
    setEditingPlayer(player);
    setShowForm(true);
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!form.name.trim()) return;

    if (editingPlayer) {
      await db.players.update(editingPlayer.id!, {
        name: form.name.trim(),
        email: form.email.trim() || undefined,
        phone: form.phone.trim() || undefined,
        rating: parseInt(form.rating) || 1200,
      });
    } else {
      await db.players.add({
        name: form.name.trim(),
        email: form.email.trim() || undefined,
        phone: form.phone.trim() || undefined,
        rating: parseInt(form.rating) || 1200,
        wins: 0,
        losses: 0,
        matchesPlayed: 0,
        createdAt: new Date(),
      });
    }

    setShowForm(false);
    setEditingPlayer(null);
    loadPlayers();
  }

  async function handleDelete(id: number) {
    if (!confirm('Delete this player? This cannot be undone.')) return;
    await db.players.delete(id);
    loadPlayers();
  }

  const filtered = players.filter((p) =>
    p.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900"> Players</h1>
          <p className="text-gray-500 mt-1">{players.length} registered players</p>
        </div>
        <button onClick={openAddForm} className="btn-primary">
          + Add Player
        </button>
      </div>

      {/* Search */}
      <input
        type="text"
        placeholder="Search players..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        className="input max-w-sm"
      />

      {/* Add/Edit Form Modal */}
      {showForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={() => setShowForm(false)}>
          <div className="bg-white rounded-xl p-6 w-full max-w-md shadow-xl" onClick={(e) => e.stopPropagation()}>
            <h2 className="text-xl font-bold mb-4">{editingPlayer ? 'Edit Player' : 'Add New Player'}</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Name *</label>
                <input
                  type="text"
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  className="input"
                  placeholder="Player name"
                  required
                  autoFocus
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                <input
                  type="email"
                  value={form.email}
                  onChange={(e) => setForm({ ...form, email: e.target.value })}
                  className="input"
                  placeholder="player@email.com"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                <input
                  type="tel"
                  value={form.phone}
                  onChange={(e) => setForm({ ...form, phone: e.target.value })}
                  className="input"
                  placeholder="+91 98765 43210"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Initial Rating</label>
                <input
                  type="number"
                  value={form.rating}
                  onChange={(e) => setForm({ ...form, rating: e.target.value })}
                  className="input"
                  min="800"
                  max="2400"
                />
                <p className="text-xs text-gray-400 mt-1">Default: 1200. Range: 800–2400</p>
              </div>
              <div className="flex gap-3 pt-2">
                <button type="submit" className="btn-primary flex-1">
                  {editingPlayer ? 'Save Changes' : 'Add Player'}
                </button>
                <button type="button" onClick={() => setShowForm(false)} className="btn-secondary flex-1">
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Players Table */}
      <div className="card overflow-hidden !p-0">
        <table className="w-full">
          <thead className="bg-gray-50 border-b border-gray-200">
            <tr>
              <th className="text-left px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">#</th>
              <th className="text-left px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">Player</th>
              <th className="text-left px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">Rating</th>
              <th className="text-left px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">Tier</th>
              <th className="text-center px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">W / L</th>
              <th className="text-center px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">Played</th>
              <th className="text-right px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filtered.map((player, idx) => {
              const tier = getRatingTier(player.rating);
              return (
                <tr key={player.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4 text-sm text-gray-400 font-mono">{idx + 1}</td>
                  <td className="px-6 py-4">
                    <p className="font-medium text-gray-900">{player.name}</p>
                    {player.email && <p className="text-xs text-gray-400">{player.email}</p>}
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-lg font-bold text-primary-700">{player.rating}</span>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`badge ${tier.color}`}>{tier.label}</span>
                  </td>
                  <td className="px-6 py-4 text-center text-sm">
                    <span className="text-shuttle-700 font-medium">{player.wins}</span>
                    <span className="text-gray-400"> / </span>
                    <span className="text-red-500 font-medium">{player.losses}</span>
                  </td>
                  <td className="px-6 py-4 text-center text-sm text-gray-600">{player.matchesPlayed}</td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => openEditForm(player)} className="text-primary-600 hover:text-primary-800 text-sm mr-3">
                      Edit
                    </button>
                    <button onClick={() => handleDelete(player.id!)} className="text-red-500 hover:text-red-700 text-sm">
                      Delete
                    </button>
                  </td>
                </tr>
              );
            })}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={7} className="px-6 py-12 text-center text-gray-400">
                  {search ? 'No players match your search' : 'No players yet. Add your first player!'}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db, type Player } from '../lib/db';
import { getRatingTier } from '../lib/elo';

export default function Players() {
  const [showForm, setShowForm] = useState(false);
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [form, setForm] = useState({ name: '', email: '', phone: '', rating: '1200' });
  const [search, setSearch] = useState('');

  // Live query for players - updates automatically when database changes
  const players = useLiveQuery(async () => 
    db.players.orderBy('rating').reverse().toArray(), []
  );

  function openAddForm() {
    setForm({ name: '', email: '', phone: '', rating: '1200' });
    setEditingPlayer(null);
    setShowForm(true);
  }

  function openEditForm(player: Player) {
    setForm({
      name: player.name,
      email: player.email || '',
      phone: player.phone || '',
      rating: String(player.rating),
    });
    setEditingPlayer(player);
    setShowForm(true);
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!form.name.trim()) return;

    if (editingPlayer) {
      await db.players.update(editingPlayer.id!, {
        name: form.name.trim(),
        email: form.email.trim() || undefined,
        phone: form.phone.trim() || undefined,
        rating: parseInt(form.rating) || 1200,
      });
    } else {
      await db.players.add({
        name: form.name.trim(),
        email: form.email.trim() || undefined,
        phone: form.phone.trim() || undefined,
        rating: parseInt(form.rating) || 1200,
        wins: 0,
        losses: 0,
        matchesPlayed: 0,
        createdAt: new Date(),
      });
    }

    setShowForm(false);
    setEditingPlayer(null);
    // No need to manually call loadPlayers - live query will update automatically
  }

  async function handleDelete(id: number) {
    if (!confirm('Delete this player? This cannot be undone.')) return;
    await db.players.delete(id);
    // Live query will automatically update
  }

  const filtered = players.filter((p) =>
    p.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900"> Players</h1>
          <p className="text-gray-500 mt-1">{players.length} registered players</p>
        </div>
        <button onClick={openAddForm} className="btn-primary">
          + Add Player
        </button>
      </div>

      {/* Search */}
      <input
        type="text"
        placeholder="Search players..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        className="input max-w-sm"
      />

      {/* Add/Edit Form Modal */}
      {showForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={() => setShowForm(false)}>
          <div className="bg-white rounded-xl p-6 w-full max-w-md shadow-xl" onClick={(e) => e.stopPropagation()}>
            <h2 className="text-xl font-bold mb-4">{editingPlayer ? 'Edit Player' : 'Add New Player'}</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Name *</label>
                <input
                  type="text"
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  className="input"
                  placeholder="Player name"
                  required
                  autoFocus
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                <input
                  type="email"
                  value={form.email}
                  onChange={(e) => setForm({ ...form, email: e.target.value })}
                  className="input"
                  placeholder="player@email.com"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                <input
                  type="tel"
                  value={form.phone}
                  onChange={(e) => setForm({ ...form, phone: e.target.value })}
                  className="input"
                  placeholder="+91 98765 43210"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Initial Rating</label>
                <input
                  type="number"
                  value={form.rating}
                  onChange={(e) => setForm({ ...form, rating: e.target.value })}
                  className="input"
                  min="800"
                  max="2400"
                />
                <p className="text-xs text-gray-400 mt-1">Default: 1200. Range: 800–2400</p>
              </div>
              <div className="flex gap-3 pt-2">
                <button type="submit" className="btn-primary flex-1">
                  {editingPlayer ? 'Save Changes' : 'Add Player'}
                </button>
                <button type="button" onClick={() => setShowForm(false)} className="btn-secondary flex-1">
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Players Table */}
      <div className="card overflow-hidden !p-0">
        <table className="w-full">
          <thead className="bg-gray-50 border-b border-gray-200">
            <tr>
              <th className="text-left px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">#</th>
              <th className="text-left px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">Player</th>
              <th className="text-left px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">Rating</th>
              <th className="text-left px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">Tier</th>
              <th className="text-center px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">W / L</th>
              <th className="text-center px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">Played</th>
              <th className="text-right px-6 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filtered.map((player, idx) => {
              const tier = getRatingTier(player.rating);
              return (
                <tr key={player.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4 text-sm text-gray-400 font-mono">{idx + 1}</td>
                  <td className="px-6 py-4">
                    <p className="font-medium text-gray-900">{player.name}</p>
                    {player.email && <p className="text-xs text-gray-400">{player.email}</p>}
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-lg font-bold text-primary-700">{player.rating}</span>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`badge ${tier.color}`}>{tier.label}</span>
                  </td>
                  <td className="px-6 py-4 text-center text-sm">
                    <span className="text-shuttle-700 font-medium">{player.wins}</span>
                    <span className="text-gray-400"> / </span>
                    <span className="text-red-500 font-medium">{player.losses}</span>
                  </td>
                  <td className="px-6 py-4 text-center text-sm text-gray-600">{player.matchesPlayed}</td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => openEditForm(player)} className="text-primary-600 hover:text-primary-800 text-sm mr-3">
                      Edit
                    </button>
                    <button onClick={() => handleDelete(player.id!)} className="text-red-500 hover:text-red-700 text-sm">
                      Delete
                    </button>
                  </td>
                </tr>
              );
            })}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={7} className="px-6 py-12 text-center text-gray-400">
                  {search ? 'No players match your search' : 'No players yet. Add your first player!'}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db, type Tournament, type Match, type Player } from '../lib/db';
import { calculateNewRatings } from '../lib/elo';

interface MatchWithPlayers extends Match {
  p1Name: string;
  p2Name: string;
  p1Rating: number;
  p2Rating: number;
}

interface Standing {
  playerId: number;
  name: string;
  rating: number;
  wins: number;
  losses: number;
  pointsFor: number;
  pointsAgainst: number;
  pointDiff: number;
}

export default function TournamentDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const [matches, setMatches] = useState<MatchWithPlayers[]>([]);
  const [standings, setStandings] = useState<Standing[]>([]);
  const [playerMap, setPlayerMap] = useState<Map<number, Player>>(new Map());
  const [activeRound, setActiveRound] = useState(1);
  const [scoreInput, setScoreInput] = useState<Record<number, { s1: string; s2: string }>>({});

  useEffect(() => {
    if (id) loadTournament(parseInt(id));
  }, [id]);

  async function loadTournament(tournamentId: number) {
    const t = await db.tournaments.get(tournamentId);
    if (!t) { navigate('/tournaments'); return; }
    setTournament(t);

    const allPlayers = await db.players.toArray();
    const pMap = new Map<number, Player>();
    allPlayers.forEach((p) => pMap.set(p.id!, p));
    setPlayerMap(pMap);

    const allMatches = await db.matches.where('tournamentId').equals(tournamentId).sortBy('scheduledOrder');
    const enriched: MatchWithPlayers[] = allMatches.map((m) => ({
      ...m,
      p1Name: pMap.get(m.player1Id)?.name || 'Unknown',
      p2Name: pMap.get(m.player2Id)?.name || 'Unknown',
      p1Rating: pMap.get(m.player1Id)?.rating || 1200,
      p2Rating: pMap.get(m.player2Id)?.rating || 1200,
    }));
    setMatches(enriched);

    // Calculate standings
    const standingsMap = new Map<number, Standing>();
    t.playerIds.forEach((pid) => {
      const p = pMap.get(pid);
      standingsMap.set(pid, {
        playerId: pid,
        name: p?.name || 'Unknown',
        rating: p?.rating || 1200,
        wins: 0, losses: 0, pointsFor: 0, pointsAgainst: 0, pointDiff: 0,
      });
    });

    allMatches.filter((m) => m.status === 'completed').forEach((m) => {
      const s1 = standingsMap.get(m.player1Id);
      const s2 = standingsMap.get(m.player2Id);
      if (s1 && m.player1Score !== null) {
        s1.pointsFor += m.player1Score;
        s1.pointsAgainst += m.player2Score || 0;
        if (m.winnerId === m.player1Id) s1.wins++; else s1.losses++;
      }
      if (s2 && m.player2Score !== null) {
        s2.pointsFor += m.player2Score;
        s2.pointsAgainst += m.player1Score || 0;
        if (m.winnerId === m.player2Id) s2.wins++; else s2.losses++;
      }
    });

    const sortedStandings = Array.from(standingsMap.values())
      .map((s) => ({ ...s, pointDiff: s.pointsFor - s.pointsAgainst }))
      .sort((a, b) => b.wins - a.wins || b.pointDiff - a.pointDiff);
    setStandings(sortedStandings);

    // Set active round to first incomplete round
    const rounds = [...new Set(allMatches.map((m) => m.round))].sort((a, b) => a - b);
    const firstIncomplete = rounds.find((r) =>
      allMatches.some((m) => m.round === r && m.status === 'pending')
    );
    if (firstIncomplete) setActiveRound(firstIncomplete);
  }

  async function startTournament() {
    if (!tournament) return;
    await db.tournaments.update(tournament.id!, { status: 'in_progress' });
    loadTournament(tournament.id!);
  }

  async function submitScore(match: MatchWithPlayers) {
    const input = scoreInput[match.id!];
    if (!input) return;

    const s1 = parseInt(input.s1);
    const s2 = parseInt(input.s2);
    if (isNaN(s1) || isNaN(s2) || s1 < 0 || s2 < 0) {
      alert('Please enter valid scores');
      return;
    }
    if (s1 === s2) {
      alert('Scores cannot be tied in badminton. Enter different scores.');
      return;
    }

    const winnerId = s1 > s2 ? match.player1Id : match.player2Id;
    const loserId = s1 > s2 ? match.player2Id : match.player1Id;

    // Update match
    await db.matches.update(match.id!, {
      player1Score: s1,
      player2Score: s2,
      winnerId,
      status: 'completed',
    });

    // Update ELO ratings
    const winner = await db.players.get(winnerId);
    const loser = await db.players.get(loserId);
    if (winner && loser) {
      const { newWinnerRating, newLoserRating } = calculateNewRatings(winner.rating, loser.rating);
      await db.players.update(winnerId, {
        rating: newWinnerRating,
        wins: winner.wins + 1,
        matchesPlayed: winner.matchesPlayed + 1,
      });
      await db.players.update(loserId, {
        rating: newLoserRating,
        losses: loser.losses + 1,
        matchesPlayed: loser.matchesPlayed + 1,
      });
    }

    // Clear input
    setScoreInput((prev) => {
      const next = { ...prev };
      delete next[match.id!];
      return next;
    });

    // Check if all matches are complete
    const remaining = await db.matches
      .where('tournamentId').equals(tournament!.id!)
      .filter((m) => m.status === 'pending')
      .count();

    if (remaining === 0) {
      await db.tournaments.update(tournament!.id!, { status: 'completed' });
    }

    loadTournament(tournament!.id!);
  }

  if (!tournament) return <div className="text-center py-12 text-gray-400">Loading...</div>;

  const rounds = [...new Set(matches.map((m) => m.round))].sort((a, b) => a - b);
  const roundMatches = matches.filter((m) => m.round === activeRound);
  const completedCount = matches.filter((m) => m.status === 'completed').length;
  const progress = matches.length > 0 ? Math.round((completedCount / matches.length) * 100) : 0;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-start justify-between">
        <div>
          <button onClick={() => navigate('/tournaments')} className="text-sm text-gray-500 hover:text-gray-700 mb-2 inline-block">
            ← Back to Tournaments
          </button>
          <h1 className="text-3xl font-bold text-gray-900">{tournament.name}</h1>
          <p className="text-gray-500 mt-1">
             {tournament.date} •  {tournament.playerIds.length} players •  {matches.length} matches
          </p>
        </div>
        {tournament.status === 'draft' && (
          <button onClick={startTournament} className="btn-success text-lg px-6 py-3">
            ▶️ Start Tournament
          </button>
        )}
      </div>

      {/* Progress Bar */}
      <div className="card">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm font-medium text-gray-700">Tournament Progress</span>
          <span className="text-sm text-gray-500">{completedCount}/{matches.length} matches ({progress}%)</span>
        </div>
        <div className="w-full bg-gray-200 rounded-full h-3">
          <div
            className={`h-3 rounded-full transition-all duration-500 ${
              progress === 100 ? 'bg-shuttle-500' : 'bg-primary-500'
            }`}
            style={{ width: `${progress}%` }}
          />
        </div>
        {tournament.status === 'completed' && (
          <p className="text-shuttle-700 font-bold text-center mt-3 text-lg"> Tournament Complete!</p>
        )}
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        {/* Matches Panel — 2 columns */}
        <div className="lg:col-span-2 space-y-4">
          <h2 className="text-xl font-bold"> Matches</h2>

          {/* Round Tabs */}
          <div className="flex gap-1 flex-wrap">
            {rounds.map((r) => {
              const roundComplete = matches.filter((m) => m.round === r).every((m) => m.status === 'completed');
              return (
                <button
                  key={r}
                  onClick={() => setActiveRound(r)}
                  className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
                    activeRound === r
                      ? 'bg-primary-600 text-white'
                      : roundComplete
                      ? 'bg-shuttle-100 text-shuttle-700'
                      : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                  }`}
                >
                  Round {r} {roundComplete && '✓'}
                </button>
              );
            })}
          </div>

          {/* Match Cards */}
          <div className="space-y-3">
            {roundMatches.map((match) => (
              <div
                key={match.id}
                className={`card !p-4 ${match.status === 'completed' ? 'border-shuttle-200 bg-shuttle-50/30' : ''}`}
              >
                <div className="flex items-center justify-between">
                  {/* Player 1 */}
                  <div className="flex-1 text-center">
                    <p className={`font-semibold ${match.winnerId === match.player1Id ? 'text-shuttle-700' : ''}`}>
                      {match.p1Name}
                    </p>
                    <p className="text-xs text-gray-400">Rating: {match.p1Rating}</p>
                  </div>

                  {/* Score / Input */}
                  <div className="flex-shrink-0 mx-4 text-center">
                    {match.status === 'completed' ? (
                      <div className="flex items-center gap-2">
                        <span className={`text-2xl font-bold ${match.winnerId === match.player1Id ? 'text-shuttle-700' : 'text-gray-400'}`}>
                          {match.player1Score}
                        </span>
                        <span className="text-gray-300">-</span>
                        <span className={`text-2xl font-bold ${match.winnerId === match.player2Id ? 'text-shuttle-700' : 'text-gray-400'}`}>
                          {match.player2Score}
                        </span>
                      </div>
                    ) : tournament.status === 'in_progress' ? (
                      <div className="flex items-center gap-2">
                        <input
                          type="number"
                          min="0"
                          max="30"
                          className="w-14 h-10 text-center input font-bold"
                          placeholder="0"
                          value={scoreInput[match.id!]?.s1 || ''}
                          onChange={(e) =>
                            setScoreInput((prev) => ({
                              ...prev,
                              [match.id!]: { ...prev[match.id!], s1: e.target.value },
                            }))
                          }
                        />
                        <span className="text-gray-400 font-bold">-</span>
                        <input
                          type="number"
                          min="0"
                          max="30"
                          className="w-14 h-10 text-center input font-bold"
                          placeholder="0"
                          value={scoreInput[match.id!]?.s2 || ''}
                          onChange={(e) =>
                            setScoreInput((prev) => ({
                              ...prev,
                              [match.id!]: { ...prev[match.id!], s2: e.target.value },
                            }))
                          }
                        />
                        <button
                          onClick={() => submitScore(match)}
                          className="btn-success text-sm px-3 py-2 ml-1"
                          disabled={!scoreInput[match.id!]?.s1 || !scoreInput[match.id!]?.s2}
                        >
                          ✓
                        </button>
                      </div>
                    ) : (
                      <span className="text-sm text-gray-400 italic">Pending</span>
                    )}
                  </div>

                  {/* Player 2 */}
                  <div className="flex-1 text-center">
                    <p className={`font-semibold ${match.winnerId === match.player2Id ? 'text-shuttle-700' : ''}`}>
                      {match.p2Name}
                    </p>
                    <p className="text-xs text-gray-400">Rating: {match.p2Rating}</p>
                  </div>
                </div>
                {match.status === 'completed' && match.winnerId && (
                  <p className="text-center text-xs text-shuttle-600 mt-2">
                     {match.winnerId === match.player1Id ? match.p1Name : match.p2Name} wins
                  </p>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Standings Panel — 1 column */}
        <div>
          <h2 className="text-xl font-bold mb-4"> Standings</h2>
          <div className="card !p-0 overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="px-3 py-2 text-left">#</th>
                  <th className="px-3 py-2 text-left">Player</th>
                  <th className="px-3 py-2 text-center">W</th>
                  <th className="px-3 py-2 text-center">L</th>
                  <th className="px-3 py-2 text-center">+/-</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {standings.map((s, idx) => (
                  <tr key={s.playerId} className={idx === 0 && tournament.status === 'completed' ? 'bg-yellow-50' : ''}>
                    <td className="px-3 py-2 font-mono text-gray-400">
                      {idx === 0 && tournament.status === 'completed' ? '' :
                       idx === 1 && tournament.status === 'completed' ? '' :
                       idx === 2 && tournament.status === 'completed' ? '' : idx + 1}
                    </td>
                    <td className="px-3 py-2 font-medium">{s.name}</td>
                    <td className="px-3 py-2 text-center text-shuttle-700 font-bold">{s.wins}</td>
                    <td className="px-3 py-2 text-center text-red-500">{s.losses}</td>
                    <td className={`px-3 py-2 text-center font-mono ${s.pointDiff > 0 ? 'text-shuttle-700' : s.pointDiff < 0 ? 'text-red-500' : 'text-gray-400'}`}>
                      {s.pointDiff > 0 ? '+' : ''}{s.pointDiff}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useLiveQuery } from 'dexie-react-hooks';
import { db, type Match, type Player } from '../lib/db';
import { calculateNewRatings } from '../lib/elo';

interface MatchWithPlayers extends Match {
  p1Name: string;
  p2Name: string;
  p1Rating: number;
  p2Rating: number;
}

interface Standing {
  playerId: number;
  name: string;
  rating: number;
  wins: number;
  losses: number;
  pointsFor: number;
  pointsAgainst: number;
  pointDiff: number;
}

export default function TournamentDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [activeRound, setActiveRound] = useState(1);
  const [scoreInput, setScoreInput] = useState<Record<number, { s1: string; s2: string }>>({});

  // Live queries for real-time updates
  const tournament = useLiveQuery(async () => 
    db.tournaments.get(parseInt(id || '0'))
  );

  const allPlayers = useLiveQuery(async () => 
    db.players.toArray(), []
  );

  const matches = useLiveQuery(async () => {
    if (!id) return [];
    const allMatches = await db.matches.where('tournamentId').equals(parseInt(id)).sortBy('scheduledOrder');
    const pMap = new Map<number, Player>();
    const players = await db.players.toArray();
    players.forEach((p) => pMap.set(p.id!, p));

    return allMatches.map((m) => ({
      ...m,
      p1Name: pMap.get(m.player1Id)?.name || 'Unknown',
      p2Name: pMap.get(m.player2Id)?.name || 'Unknown',
      p1Rating: pMap.get(m.player1Id)?.rating || 1200,
      p2Rating: pMap.get(m.player2Id)?.rating || 1200,
    }));
  }, []);

  // Calculate standings dynamically from live matches
  const standings = useMemo(() => {
    if (!tournament) return [];

    const standingsMap = new Map<number, Standing>();
    tournament.playerIds.forEach((pid) => {
      const p = allPlayers.find(pl => pl.id === pid);
      standingsMap.set(pid, {
        playerId: pid,
        name: p?.name || 'Unknown',
        rating: p?.rating || 1200,
        wins: 0, losses: 0, pointsFor: 0, pointsAgainst: 0, pointDiff: 0,
      });
    });

    matches.filter((m) => m.status === 'completed').forEach((m) => {
      const s1 = standingsMap.get(m.player1Id);
      const s2 = standingsMap.get(m.player2Id);
      if (s1 && m.player1Score !== null) {
        s1.pointsFor += m.player1Score;
        s1.pointsAgainst += m.player2Score || 0;
        if (m.winnerId === m.player1Id) s1.wins++; else s1.losses++;
      }
      if (s2 && m.player2Score !== null) {
        s2.pointsFor += m.player2Score;
        s2.pointsAgainst += m.player1Score || 0;
        if (m.winnerId === m.player2Id) s2.wins++; else s2.losses++;
      }
    });

    return Array.from(standingsMap.values())
      .map((s) => ({ ...s, pointDiff: s.pointsFor - s.pointsAgainst }))
      .sort((a, b) => b.wins - a.wins || b.pointDiff - a.pointDiff);
  }, [tournament, matches, allPlayers]);

  async function startTournament() {
    if (!tournament) return;
    await db.tournaments.update(tournament.id!, { status: 'in_progress' });
    // Live query will automatically update
  }

  async function submitScore(match: MatchWithPlayers) {
    const input = scoreInput[match.id!];
    if (!input) return;

    const s1 = parseInt(input.s1);
    const s2 = parseInt(input.s2);
    if (isNaN(s1) || isNaN(s2) || s1 < 0 || s2 < 0) {
      alert('Please enter valid scores');
      return;
    }
    if (s1 === s2) {
      alert('Scores cannot be tied in badminton. Enter different scores.');
      return;
    }

    const winnerId = s1 > s2 ? match.player1Id : match.player2Id;
    const loserId = s1 > s2 ? match.player2Id : match.player1Id;

    // Update match
    await db.matches.update(match.id!, {
      player1Score: s1,
      player2Score: s2,
      winnerId,
      status: 'completed',
    });

    // Update ELO ratings
    const winner = await db.players.get(winnerId);
    const loser = await db.players.get(loserId);
    if (winner && loser) {
      const { newWinnerRating, newLoserRating } = calculateNewRatings(winner.rating, loser.rating);
      await db.players.update(winnerId, {
        rating: newWinnerRating,
        wins: winner.wins + 1,
        matchesPlayed: winner.matchesPlayed + 1,
      });
      await db.players.update(loserId, {
        rating: newLoserRating,
        losses: loser.losses + 1,
        matchesPlayed: loser.matchesPlayed + 1,
      });
    }

    // Clear input
    setScoreInput((prev) => {
      const next = { ...prev };
      delete next[match.id!];
      return next;
    });

    // Check if all matches are complete
    const remaining = await db.matches
      .where('tournamentId').equals(tournament!.id!)
      .filter((m) => m.status === 'pending')
      .count();

    if (remaining === 0) {
      await db.tournaments.update(tournament!.id!, { status: 'completed' });
    }

    // Live query will automatically update
  }

  if (!tournament) {
    if (tournament === null && id) {
      // Tournament not found, redirect
      return navigate('/tournaments');
    }
    return <div className="text-center py-12 text-gray-400">Loading...</div>;
  }

  const rounds = [...new Set(matches.map((m) => m.round))].sort((a, b) => a - b);
  const roundMatches = matches.filter((m) => m.round === activeRound);
  const completedCount = matches.filter((m) => m.status === 'completed').length;
  const progress = matches.length > 0 ? Math.round((completedCount / matches.length) * 100) : 0;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-start justify-between">
        <div>
          <button onClick={() => navigate('/tournaments')} className="text-sm text-gray-500 hover:text-gray-700 mb-2 inline-block">
            ← Back to Tournaments
          </button>
          <h1 className="text-3xl font-bold text-gray-900">{tournament.name}</h1>
          <p className="text-gray-500 mt-1">
             {tournament.date} •  {tournament.playerIds.length} players •  {matches.length} matches
          </p>
        </div>
        {tournament.status === 'draft' && (
          <button onClick={startTournament} className="btn-success text-lg px-6 py-3">
            ▶️ Start Tournament
          </button>
        )}
      </div>

      {/* Progress Bar */}
      <div className="card">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm font-medium text-gray-700">Tournament Progress</span>
          <span className="text-sm text-gray-500">{completedCount}/{matches.length} matches ({progress}%)</span>
        </div>
        <div className="w-full bg-gray-200 rounded-full h-3">
          <div
            className={`h-3 rounded-full transition-all duration-500 ${
              progress === 100 ? 'bg-shuttle-500' : 'bg-primary-500'
            }`}
            style={{ width: `${progress}%` }}
          />
        </div>
        {tournament.status === 'completed' && (
          <p className="text-shuttle-700 font-bold text-center mt-3 text-lg"> Tournament Complete!</p>
        )}
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        {/* Matches Panel — 2 columns */}
        <div className="lg:col-span-2 space-y-4">
          <h2 className="text-xl font-bold"> Matches</h2>

          {/* Round Tabs */}
          <div className="flex gap-1 flex-wrap">
            {rounds.map((r) => {
              const roundComplete = matches.filter((m) => m.round === r).every((m) => m.status === 'completed');
              return (
                <button
                  key={r}
                  onClick={() => setActiveRound(r)}
                  className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
                    activeRound === r
                      ? 'bg-primary-600 text-white'
                      : roundComplete
                      ? 'bg-shuttle-100 text-shuttle-700'
                      : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                  }`}
                >
                  Round {r} {roundComplete && '✓'}
                </button>
              );
            })}
          </div>

          {/* Match Cards */}
          <div className="space-y-3">
            {roundMatches.map((match) => (
              <div
                key={match.id}
                className={`card !p-4 ${match.status === 'completed' ? 'border-shuttle-200 bg-shuttle-50/30' : ''}`}
              >
                <div className="flex items-center justify-between">
                  {/* Player 1 */}
                  <div className="flex-1 text-center">
                    <p className={`font-semibold ${match.winnerId === match.player1Id ? 'text-shuttle-700' : ''}`}>
                      {match.p1Name}
                    </p>
                    <p className="text-xs text-gray-400">Rating: {match.p1Rating}</p>
                  </div>

                  {/* Score / Input */}
                  <div className="flex-shrink-0 mx-4 text-center">
                    {match.status === 'completed' ? (
                      <div className="flex items-center gap-2">
                        <span className={`text-2xl font-bold ${match.winnerId === match.player1Id ? 'text-shuttle-700' : 'text-gray-400'}`}>
                          {match.player1Score}
                        </span>
                        <span className="text-gray-300">-</span>
                        <span className={`text-2xl font-bold ${match.winnerId === match.player2Id ? 'text-shuttle-700' : 'text-gray-400'}`}>
                          {match.player2Score}
                        </span>
                      </div>
                    ) : tournament.status === 'in_progress' ? (
                      <div className="flex items-center gap-2">
                        <input
                          type="number"
                          min="0"
                          max="30"
                          className="w-14 h-10 text-center input font-bold"
                          placeholder="0"
                          value={scoreInput[match.id!]?.s1 || ''}
                          onChange={(e) =>
                            setScoreInput((prev) => ({
                              ...prev,
                              [match.id!]: { ...prev[match.id!], s1: e.target.value },
                            }))
                          }
                        />
                        <span className="text-gray-400 font-bold">-</span>
                        <input
                          type="number"
                          min="0"
                          max="30"
                          className="w-14 h-10 text-center input font-bold"
                          placeholder="0"
                          value={scoreInput[match.id!]?.s2 || ''}
                          onChange={(e) =>
                            setScoreInput((prev) => ({
                              ...prev,
                              [match.id!]: { ...prev[match.id!], s2: e.target.value },
                            }))
                          }
                        />
                        <button
                          onClick={() => submitScore(match)}
                          className="btn-success text-sm px-3 py-2 ml-1"
                          disabled={!scoreInput[match.id!]?.s1 || !scoreInput[match.id!]?.s2}
                        >
                          ✓
                        </button>
                      </div>
                    ) : (
                      <span className="text-sm text-gray-400 italic">Pending</span>
                    )}
                  </div>

                  {/* Player 2 */}
                  <div className="flex-1 text-center">
                    <p className={`font-semibold ${match.winnerId === match.player2Id ? 'text-shuttle-700' : ''}`}>
                      {match.p2Name}
                    </p>
                    <p className="text-xs text-gray-400">Rating: {match.p2Rating}</p>
                  </div>
                </div>
                {match.status === 'completed' && match.winnerId && (
                  <p className="text-center text-xs text-shuttle-600 mt-2">
                     {match.winnerId === match.player1Id ? match.p1Name : match.p2Name} wins
                  </p>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Standings Panel — 1 column */}
        <div>
          <h2 className="text-xl font-bold mb-4"> Standings</h2>
          <div className="card !p-0 overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="px-3 py-2 text-left">#</th>
                  <th className="px-3 py-2 text-left">Player</th>
                  <th className="px-3 py-2 text-center">W</th>
                  <th className="px-3 py-2 text-center">L</th>
                  <th className="px-3 py-2 text-center">+/-</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {standings.map((s, idx) => (
                  <tr key={s.playerId} className={idx === 0 && tournament.status === 'completed' ? 'bg-yellow-50' : ''}>
                    <td className="px-3 py-2 font-mono text-gray-400">
                      {idx === 0 && tournament.status === 'completed' ? '' :
                       idx === 1 && tournament.status === 'completed' ? '' :
                       idx === 2 && tournament.status === 'completed' ? '' : idx + 1}
                    </td>
                    <td className="px-3 py-2 font-medium">{s.name}</td>
                    <td className="px-3 py-2 text-center text-shuttle-700 font-bold">{s.wins}</td>
                    <td className="px-3 py-2 text-center text-red-500">{s.losses}</td>
                    <td className={`px-3 py-2 text-center font-mono ${s.pointDiff > 0 ? 'text-shuttle-700' : s.pointDiff < 0 ? 'text-red-500' : 'text-gray-400'}`}>
                      {s.pointDiff > 0 ? '+' : ''}{s.pointDiff}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { db, type Player, type Tournament } from '../lib/db';
import { generateRoundRobin, matchesToDbFormat, getTotalRounds, getMatchesPerRound } from '../lib/roundRobin';

export default function Tournaments() {
  const navigate = useNavigate();
  const [tournaments, setTournaments] = useState<Tournament[]>([]);
  const [players, setPlayers] = useState<Player[]>([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ name: '', date: '', selectedPlayerIds: [] as number[] });

  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    const [allT, allP] = await Promise.all([
      db.tournaments.orderBy('date').reverse().toArray(),
      db.players.orderBy('name').toArray(),
    ]);
    setTournaments(allT);
    setPlayers(allP);
  }

  function togglePlayer(id: number) {
    setForm((prev) => ({
      ...prev,
      selectedPlayerIds: prev.selectedPlayerIds.includes(id)
        ? prev.selectedPlayerIds.filter((pid) => pid !== id)
        : [...prev.selectedPlayerIds, id],
    }));
  }

  function selectAll() {
    setForm((prev) => ({
      ...prev,
      selectedPlayerIds: prev.selectedPlayerIds.length === players.length ? [] : players.map((p) => p.id!),
    }));
  }

  async function handleCreate(e: React.FormEvent) {
    e.preventDefault();
    if (form.selectedPlayerIds.length < 3) {
      alert('Need at least 3 players for a round robin tournament');
      return;
    }
    if (!form.name.trim() || !form.date) return;

    // Create tournament
    const tournamentId = await db.tournaments.add({
      name: form.name.trim(),
      date: form.date,
      status: 'draft',
      playerIds: form.selectedPlayerIds,
      format: 'round_robin',
      createdAt: new Date(),
    });

    // Generate round robin matches
    const rrMatches = generateRoundRobin(form.selectedPlayerIds);
    const dbMatches = matchesToDbFormat(tournamentId as number, rrMatches);
    await db.matches.bulkAdd(dbMatches);

    setShowForm(false);
    loadData();
    navigate(`/tournaments/${tournamentId}`);
  }

  async function handleDelete(id: number) {
    if (!confirm('Delete this tournament and all its matches?')) return;
    await db.matches.where('tournamentId').equals(id).delete();
    await db.standings.where('tournamentId').equals(id).delete();
    await db.tournaments.delete(id);
    loadData();
  }

  const statusColors: Record<string, string> = {
    draft: 'bg-gray-100 text-gray-700',
    in_progress: 'bg-blue-100 text-blue-700',
    completed: 'bg-green-100 text-green-700',
  };

  const statusLabels: Record<string, string> = {
    draft: ' Draft',
    in_progress: ' In Progress',
    completed: '✅ Completed',
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900"> Tournaments</h1>
          <p className="text-gray-500 mt-1">{tournaments.length} tournaments</p>
        </div>
        <button onClick={() => {
          setForm({ name: '', date: new Date().toISOString().split('T')[0], selectedPlayerIds: [] });
          setShowForm(true);
        }} className="btn-primary">
          + New Tournament
        </button>
      </div>

      {/* Create Tournament Modal */}
      {showForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={() => setShowForm(false)}>
          <div className="bg-white rounded-xl p-6 w-full max-w-lg shadow-xl max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
            <h2 className="text-xl font-bold mb-4"> New Tournament</h2>
            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Tournament Name *</label>
                <input
                  type="text"
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  className="input"
                  placeholder="Weekend Smash Series"
                  required
                  autoFocus
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Date *</label>
                <input
                  type="date"
                  value={form.date}
                  onChange={(e) => setForm({ ...form, date: e.target.value })}
                  className="input"
                  required
                />
              </div>
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="block text-sm font-medium text-gray-700">
                    Select Players * ({form.selectedPlayerIds.length} selected)
                  </label>
                  <button type="button" onClick={selectAll} className="text-xs text-primary-600 hover:underline">
                    {form.selectedPlayerIds.length === players.length ? 'Deselect All' : 'Select All'}
                  </button>
                </div>
                {players.length === 0 ? (
                  <p className="text-sm text-gray-400">No players registered. <Link to="/players" className="text-primary-600 underline">Add players first</Link></p>
                ) : (
                  <div className="grid grid-cols-2 gap-2 max-h-60 overflow-y-auto border border-gray-200 rounded-lg p-3">
                    {players.map((p) => (
                      <label
                        key={p.id}
                        className={`flex items-center gap-2 p-2 rounded-lg cursor-pointer transition-colors ${
                          form.selectedPlayerIds.includes(p.id!)
                            ? 'bg-primary-50 border border-primary-200'
                            : 'hover:bg-gray-50 border border-transparent'
                        }`}
                      >
                        <input
                          type="checkbox"
                          checked={form.selectedPlayerIds.includes(p.id!)}
                          onChange={() => togglePlayer(p.id!)}
                          className="rounded text-primary-600"
                        />
                        <div>
                          <p className="text-sm font-medium">{p.name}</p>
                          <p className="text-xs text-gray-400">Rating: {p.rating}</p>
                        </div>
                      </label>
                    ))}
                  </div>
                )}
                {form.selectedPlayerIds.length >= 3 && (
                  <p className="text-xs text-gray-500 mt-2">
                     {getTotalRounds(form.selectedPlayerIds.length)} rounds, {getMatchesPerRound(form.selectedPlayerIds.length)} matches/round,{' '}
                    {getTotalRounds(form.selectedPlayerIds.length) * getMatchesPerRound(form.selectedPlayerIds.length)} total matches
                  </p>
                )}
              </div>
              <div className="flex gap-3 pt-2">
                <button
                  type="submit"
                  className="btn-primary flex-1"
                  disabled={form.selectedPlayerIds.length < 3}
                >
                  Create Tournament
                </button>
                <button type="button" onClick={() => setShowForm(false)} className="btn-secondary flex-1">
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Tournament List */}
      <div className="space-y-4">
        {tournaments.map((t) => (
          <div key={t.id} className="card flex items-center justify-between">
            <div>
              <div className="flex items-center gap-3">
                <h3 className="text-lg font-bold">{t.name}</h3>
                <span className={`badge ${statusColors[t.status]}`}>{statusLabels[t.status]}</span>
              </div>
              <p className="text-sm text-gray-500 mt-1">
                 {t.date} •  {t.playerIds.length} players •  {t.format.replace('_', ' ')}
              </p>
            </div>
            <div className="flex items-center gap-2">
              <Link to={`/tournaments/${t.id}`} className="btn-primary text-sm">
                View →
              </Link>
              {t.status === 'draft' && (
                <button onClick={() => handleDelete(t.id!)} className="btn-danger text-sm">
                  Delete
                </button>
              )}
            </div>
          </div>
        ))}
        {tournaments.length === 0 && (
          <div className="card text-center py-12 text-gray-400">
            <p className="text-4xl mb-3"></p>
            <p className="text-lg">No tournaments yet</p>
            <p className="text-sm mt-1">Create your first round robin tournament!</p>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useLiveQuery } from 'dexie-react-hooks';
import { db } from '../lib/db';
import { generateRoundRobin, matchesToDbFormat, getTotalRounds, getMatchesPerRound } from '../lib/roundRobin';

export default function Tournaments() {
  const navigate = useNavigate();
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ name: '', date: '', selectedPlayerIds: [] as number[] });

  // Live queries for real-time updates
  const tournaments = useLiveQuery(async () => 
    db.tournaments.orderBy('date').reverse().toArray(), []
  );

  const players = useLiveQuery(async () => 
    db.players.orderBy('name').toArray(), []
  );

  function togglePlayer(id: number) {
    setForm((prev) => ({
      ...prev,
      selectedPlayerIds: prev.selectedPlayerIds.includes(id)
        ? prev.selectedPlayerIds.filter((pid) => pid !== id)
        : [...prev.selectedPlayerIds, id],
    }));
  }

  function selectAll() {
    setForm((prev) => ({
      ...prev,
      selectedPlayerIds: prev.selectedPlayerIds.length === players.length ? [] : players.map((p) => p.id!),
    }));
  }

  async function handleCreate(e: React.FormEvent) {
    e.preventDefault();
    if (form.selectedPlayerIds.length < 3) {
      alert('Need at least 3 players for a round robin tournament');
      return;
    }
    if (!form.name.trim() || !form.date) return;

    // Create tournament
    const tournamentId = await db.tournaments.add({
      name: form.name.trim(),
      date: form.date,
      status: 'draft',
      playerIds: form.selectedPlayerIds,
      format: 'round_robin',
      createdAt: new Date(),
    });

    // Generate round robin matches
    const rrMatches = generateRoundRobin(form.selectedPlayerIds);
    const dbMatches = matchesToDbFormat(tournamentId as number, rrMatches);
    await db.matches.bulkAdd(dbMatches);

    setShowForm(false);
    navigate(`/tournaments/${tournamentId}`);
    // Live query will automatically update
  }

  async function handleDelete(id: number) {
    if (!confirm('Delete this tournament and all its matches?')) return;
    await db.matches.where('tournamentId').equals(id).delete();
    await db.standings.where('tournamentId').equals(id).delete();
    await db.tournaments.delete(id);
    // Live query will automatically update
  }

  const statusColors: Record<string, string> = {
    draft: 'bg-gray-100 text-gray-700',
    in_progress: 'bg-blue-100 text-blue-700',
    completed: 'bg-green-100 text-green-700',
  };

  const statusLabels: Record<string, string> = {
    draft: ' Draft',
    in_progress: ' In Progress',
    completed: '✅ Completed',
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900"> Tournaments</h1>
          <p className="text-gray-500 mt-1">{tournaments.length} tournaments</p>
        </div>
        <button onClick={() => {
          setForm({ name: '', date: new Date().toISOString().split('T')[0], selectedPlayerIds: [] });
          setShowForm(true);
        }} className="btn-primary">
          + New Tournament
        </button>
      </div>

      {/* Create Tournament Modal */}
      {showForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={() => setShowForm(false)}>
          <div className="bg-white rounded-xl p-6 w-full max-w-lg shadow-xl max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
            <h2 className="text-xl font-bold mb-4"> New Tournament</h2>
            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Tournament Name *</label>
                <input
                  type="text"
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  className="input"
                  placeholder="Weekend Smash Series"
                  required
                  autoFocus
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Date *</label>
                <input
                  type="date"
                  value={form.date}
                  onChange={(e) => setForm({ ...form, date: e.target.value })}
                  className="input"
                  required
                />
              </div>
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="block text-sm font-medium text-gray-700">
                    Select Players * ({form.selectedPlayerIds.length} selected)
                  </label>
                  <button type="button" onClick={selectAll} className="text-xs text-primary-600 hover:underline">
                    {form.selectedPlayerIds.length === players.length ? 'Deselect All' : 'Select All'}
                  </button>
                </div>
                {players.length === 0 ? (
                  <p className="text-sm text-gray-400">No players registered. <Link to="/players" className="text-primary-600 underline">Add players first</Link></p>
                ) : (
                  <div className="grid grid-cols-2 gap-2 max-h-60 overflow-y-auto border border-gray-200 rounded-lg p-3">
                    {players.map((p) => (
                      <label
                        key={p.id}
                        className={`flex items-center gap-2 p-2 rounded-lg cursor-pointer transition-colors ${
                          form.selectedPlayerIds.includes(p.id!)
                            ? 'bg-primary-50 border border-primary-200'
                            : 'hover:bg-gray-50 border border-transparent'
                        }`}
                      >
                        <input
                          type="checkbox"
                          checked={form.selectedPlayerIds.includes(p.id!)}
                          onChange={() => togglePlayer(p.id!)}
                          className="rounded text-primary-600"
                        />
                        <div>
                          <p className="text-sm font-medium">{p.name}</p>
                          <p className="text-xs text-gray-400">Rating: {p.rating}</p>
                        </div>
                      </label>
                    ))}
                  </div>
                )}
                {form.selectedPlayerIds.length >= 3 && (
                  <p className="text-xs text-gray-500 mt-2">
                     {getTotalRounds(form.selectedPlayerIds.length)} rounds, {getMatchesPerRound(form.selectedPlayerIds.length)} matches/round,{' '}
                    {getTotalRounds(form.selectedPlayerIds.length) * getMatchesPerRound(form.selectedPlayerIds.length)} total matches
                  </p>
                )}
              </div>
              <div className="flex gap-3 pt-2">
                <button
                  type="submit"
                  className="btn-primary flex-1"
                  disabled={form.selectedPlayerIds.length < 3}
                >
                  Create Tournament
                </button>
                <button type="button" onClick={() => setShowForm(false)} className="btn-secondary flex-1">
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Tournament List */}
      <div className="space-y-4">
        {tournaments.map((t) => (
          <div key={t.id} className="card flex items-center justify-between">
            <div>
              <div className="flex items-center gap-3">
                <h3 className="text-lg font-bold">{t.name}</h3>
                <span className={`badge ${statusColors[t.status]}`}>{statusLabels[t.status]}</span>
              </div>
              <p className="text-sm text-gray-500 mt-1">
                 {t.date} •  {t.playerIds.length} players •  {t.format.replace('_', ' ')}
              </p>
            </div>
            <div className="flex items-center gap-2">
              <Link to={`/tournaments/${t.id}`} className="btn-primary text-sm">
                View →
              </Link>
              {t.status === 'draft' && (
                <button onClick={() => handleDelete(t.id!)} className="btn-danger text-sm">
                  Delete
                </button>
              )}
            </div>
          </div>
        ))}
        {tournaments.length === 0 && (
          <div className="card text-center py-12 text-gray-400">
            <p className="text-4xl mb-3"></p>
            <p className="text-lg">No tournaments yet</p>
            <p className="text-sm mt-1">Create your first round robin tournament!</p>
          </div>
        )}
      </div>
    </div>
  );
}
